/* IMAGES: the three concept pictures, stored as text so the site is just 2 files.
   Do not edit by hand. To change a picture, ask for a new images.js. */
window.IMG={
 food:"data:image/jpeg;base64,",
 decor:"data:image/jpeg;base64,",
 perfume:"data:image/jpeg;base64,",
};
(function(){document.querySelectorAll('img[data-img]').forEach(function(i){i.src=window.IMG[i.getAttribute('data-img')]})})();
